variable {U : Set Coordinate4} {g : TensorField4} {Gamma : ConnectionField4} {p v : Coordinate4}
  (P : EquilibriumScreenData U g Gamma p v) (T : TensorField4) (rate : ℝ)

def screenHeatFlux (t : ℝ) : ℝ :=
  -rate*t*tensorQuad (T (P.curve t)) (P.velocity (P.curve t))*
    inducedArea g P.curve P.screen.vectors t

def coherentStateCurve (a b u v : ℝ) (hs : u^2+v^2=1)
    (w : CovectorField4) (x direction : Coordinate4) : DiagonalStateCurve (baseWeights u v) :=
  unitaryStateCurve a b (covectorRead (w x) direction) u v hs

def positiveCoupling : ℝ := coherentCoupling (-3/5) (4/5) (3/5) (4/5)
def negativeCoupling : ℝ := coherentCoupling 0 1 (3/5) (4/5)

theorem positive_coupling_positive : 0<positiveCoupling :=
  coherent_negative_control_coupling_positive

theorem negative_coupling_negative : negativeCoupling<0 := by
  unfold negativeCoupling coherentCoupling
  exact div_neg_of_neg_of_pos (neg_neg_of_pos positive_control_response_strict) Real.pi_pos

def positiveScale : ℝ := Real.sqrt (8/positiveCoupling)
def negativeScale : ℝ := Real.sqrt (8/(-negativeCoupling))

def calibrationCovector (A : Tensor4) (j : CalibrationIndex) : Coordinate4 :=
  if j.2=0 then positiveScale • plusCovector A j.1
  else negativeScale • minusCovector A j.1

def calibratedStress (g gi A : Tensor4) : Tensor4 :=
  ∑ j : CalibrationIndex, ((1:ℝ)/8) • covectorStress g gi (calibrationCovector A j)
    (coherentCoupling (calibrationAxisA j) (calibrationAxisB j) (3/5) (4/5))

def boostField (rate : ℝ) (x : Coordinate4) : Coordinate4 :=
  ![-rate * x 3, 0, 0, -rate * x 0]

def boostGenerator (rate : ℝ) : Tensor4 :=
  !![0,0,0,-rate; 0,0,0,0; 0,0,0,0; -rate,0,0,0]

def boostEven (rate s : ℝ) : ℝ :=
  (Real.exp (-rate*s) + Real.exp (rate*s))/2

def boostOdd (rate s : ℝ) : ℝ :=
  (Real.exp (-rate*s) - Real.exp (rate*s))/2

/-- The actual differential of the finite boost map. -/
def boostMatrix (rate s : ℝ) : Tensor4 :=
  !![boostEven rate s,0,0,boostOdd rate s;
    0,1,0,0; 0,0,1,0;
    boostOdd rate s,0,0,boostEven rate s]

